const products = $input.all().map(item => item.json);
const prefs = $('Webhook').first().json.body || {};
const keywords = Array.isArray(prefs.keywords) ? prefs.keywords : [];
const requestedCategory = (prefs.category || '').toLowerCase();
const terms = [...new Set([...keywords, prefs.use_case || ''].flatMap(part => ((part || '').toLowerCase().match(/[a-z0-9]+/g) || [])))];
const positiveCategoryTerms = ['speakers', 'bluetoothspeakers', 'outdoorspeakers'];
const negativeCategoryTerms = ['cables', 'adapter', 'adapters', 'receiver', 'receivers', 'smartwatch', 'smartwatches'];

function includesAny(text, tokens) {
  return tokens.some(token => text.includes(token));
}

function score(p) {
  const name = (p.product_name || '').toLowerCase();
  const about = (p.about_product || '').toLowerCase();
  const category = (p.category || '').toLowerCase();
  let matchScore = 0;

  if (requestedCategory) {
    if (category.startsWith(requestedCategory)) {
      matchScore += 8;
    } else if (category.includes(requestedCategory)) {
      matchScore += 4;
    }
  }

  if (includesAny(category, positiveCategoryTerms)) {
    matchScore += 20;
  }
  if (includesAny(category, negativeCategoryTerms)) {
    matchScore -= 18;
  }

  for (const term of terms) {
    if (name.includes(term)) {
      matchScore += 8;
    }
    if (category.includes(term)) {
      matchScore += 6;
    } else if (about.includes(term)) {
      matchScore += 2;
    }
  }

  if ((name.includes('bluetooth') && name.includes('speaker')) || category.includes('bluetoothspeakers')) {
    matchScore += 10;
  }
  if ((name.includes('portable') || about.includes('portable') || category.includes('outdoorspeakers')) && terms.includes('travel')) {
    matchScore += 4;
  }

  const rating = p.rating || 0;
  const popularity = Math.log((p.rating_count || 0) + 1);
  return matchScore * 10 + rating + popularity;
}

const ranked = [...products].sort((a, b) => score(b) - score(a));
return [{ json: { ranked } }];

const { ranked } = $input.first().json;
const top3 = ranked.slice(0, 3);

function keyFeatures(product) {
  const raw = (product.about_product || '').split('|');
  const cleaned = raw.map(feature => feature.trim()).filter(Boolean);
  return cleaned.slice(0, 3).join(' | ') || 'N/A';
}

const comparison = [
  { attribute: 'Price (₹)', values: top3.map(p => p.discounted_price != null ? `${Math.round(p.discounted_price)}` : 'N/A') },
  { attribute: 'Rating', values: top3.map(p => p.rating != null ? p.rating.toFixed(1) : 'N/A') },
  { attribute: 'Discount', values: top3.map(p => p.discount_percentage != null ? `${p.discount_percentage}%` : 'N/A') },
  { attribute: 'Key Features', values: top3.map(keyFeatures) },
];

return [{ json: { products: top3, comparison } }];
